use crate::domain::{ProviderInstance, ProviderTemplate};
use crate::opencode_config;
use std::collections::{HashMap, HashSet};
use std::fs;
use std::io::Write;
use std::path::{Path, PathBuf};

/// 渲染 aliases.zsh 内容（不写盘，不生成 opencode 配置文件）。
/// 供 Web 预览使用。
pub fn render_aliases(instances: &[ProviderInstance], templates: &[ProviderTemplate]) -> String {
    let mut lines = vec![
        "# Auto-generated by cc-switch-tui. Do not edit manually.".to_string(),
        "emulate zsh".to_string(),
    ];

    let all_env_vars = get_all_env_vars(templates);
    lines.push(format_print_env_helper(&all_env_vars));

    for instance in instances {
        if instance.alias.is_empty() {
            continue;
        }
        let env = build_env(instance, templates);
        let function_def = format_function(
            &instance.alias,
            &env,
            &all_env_vars,
            instance.kv_cache_enabled,
        );
        lines.push(function_def);
    }

    // 包含 opencode alias 引用（不写 opencode 配置文件本身）
    // 这里我们需要 config_paths，但因为不写盘，所以用占位符
    // 简化：直接复用 build_opencode_aliases 但传空 paths（生成的 alias 引用本地路径）
    let dummy_paths: HashMap<String, PathBuf> = instances
        .iter()
        .filter(|i| !i.alias.is_empty())
        .map(|i| {
            (
                i.alias.clone(),
                PathBuf::from(format!("~/.cc-switch-tui/opencode/{}.json", i.alias)),
            )
        })
        .collect();
    let opencode_lines =
        opencode_config::build_opencode_aliases(instances, templates, &dummy_paths);
    lines.extend(opencode_lines);

    // ys-proxy wrapper — 通过本地代理转发 Claude Code 请求
    // 在子 shell 中设置 proxy BASE_URL，然后调用 alias 函数
    // alias 函数内部使用 ${ANTHROPIC_BASE_URL:-默认值} 保留外部传入的值
    lines.push(
        "function ys-proxy {\n  local alias_name=$1\n  shift\n  (\n    export ANTHROPIC_BASE_URL=\"http://localhost:7480/ys-proxy/${alias_name}\"\n    $alias_name \"$@\"\n  )\n}"
            .to_string(),
    );

    lines.join("\n") + "\n"
}

/// 写入 aliases.zsh 到 dir/aliases.zsh（不生成 opencode 配置文件）。
pub fn write_aliases(dir: &Path, content: &str) -> std::io::Result<PathBuf> {
    fs::create_dir_all(dir)?;
    let path = dir.join("aliases.zsh");
    fs::write(&path, content)?;
    Ok(path)
}

/// 生成 aliases.zsh 文件（同时生成 cl-* 和 oc-* alias，**并**生成 opencode 配置文件）。
/// 保留向后兼容 — main.rs 启动时预生成时仍调用。
pub fn generate_aliases(
    dir: &std::path::Path,
    instances: &[ProviderInstance],
    templates: &[ProviderTemplate],
) -> std::io::Result<()> {
    let content = render_aliases(instances, templates);

    // 同时生成 opencode 配置文件
    let _config_paths = opencode_config::generate_opencode_configs(dir, instances, templates)?;

    write_aliases(dir, &content)?;
    Ok(())
}

fn build_env(
    instance: &ProviderInstance,
    templates: &[ProviderTemplate],
) -> HashMap<String, String> {
    let mut env = HashMap::new();
    if let Some(template) = templates.iter().find(|t| t.id == instance.template_id) {
        env.extend(template.default_env.clone());
        if let Some(model) = template.models.iter().find(|m| m.id == instance.model_id) {
            env.extend(model.env_overrides.clone());
        }
    }
    // 若实例开启了 context window 且模型有预设值，注入相关环境变量
    if instance.context_window_enabled {
        if let Some(template) = templates.iter().find(|t| t.id == instance.template_id) {
            if let Some(model) = template.models.iter().find(|m| m.id == instance.model_id) {
                if let Some(window) = model.context_window {
                    env.insert("DISABLE_COMPACT".to_string(), "1".to_string());
                    env.insert("CLAUDE_CODE_MAX_CONTEXT_TOKENS".to_string(), window.to_string());
                    env.insert("CLAUDE_CODE_AUTO_COMPACT_WINDOW".to_string(), window.to_string());
                }
            }
        }
    }
    env.insert("ANTHROPIC_AUTH_TOKEN".to_string(), instance.api_key.clone());
    env.insert(
        "CMUX_PRESERVE_CLAUDE_AUTH_SELECTION_ENV".to_string(),
        "1".to_string(),
    );
    env.insert("CC_SWITCH_ALIAS".to_string(), instance.alias.clone());
    env
}

/// 收集所有需要 unset 的环境变量（来自所有模板）
fn get_all_env_vars(templates: &[ProviderTemplate]) -> Vec<String> {
    let mut set: HashSet<String> = HashSet::from([
        "ANTHROPIC_AUTH_TOKEN".to_string(),
        "CMUX_PRESERVE_CLAUDE_AUTH_SELECTION_ENV".to_string(),
        "CC_SWITCH_ALIAS".to_string(),
        "DISABLE_COMPACT".to_string(),
        "CLAUDE_CODE_MAX_CONTEXT_TOKENS".to_string(),
        "CLAUDE_CODE_AUTO_COMPACT_WINDOW".to_string(),
    ]);
    for template in templates {
        set.extend(template.default_env.keys().cloned());
        for model in &template.models {
            set.extend(model.env_overrides.keys().cloned());
        }
    }
    let mut vars: Vec<String> = set.into_iter().collect();
    vars.sort();
    vars
}

/// 生成 __cc_switch_print_env helper 函数定义，用于在 cl-* alias 中打印实际生效的 env
fn format_print_env_helper(all_env_vars: &[String]) -> String {
    let keys_list = all_env_vars
        .iter()
        .map(|k| format!("    {}", k))
        .collect::<Vec<_>>()
        .join("\n");

    format!(
        "function __cc_switch_print_env {{\n\
         \
  local alias_name=$1\n\
         \
  [[ -n $CC_SWITCH_QUIET ]] && return 0\n\
         \
\n\
         \
  local -a keys=(\n{}\n  )\n\
         \
\n\
         \
  local parts=()\n\
         \
  for k in $keys; do\n\
         \
    local v=${{(P)k}}\n\
         \
    if [[ -z $v ]]; then\n\
         \
      parts+=(\"$k=<unset>\")\n\
         \
    elif [[ $k =~ '(_TOKEN|_API_KEY|_SECRET|_PASSWORD)$' ]]; then\n\
         \
      parts+=(\"$k=<redacted>\")\n\
         \
    else\n\
         \
      parts+=(\"$k=$v\")\n\
         \
    fi\n\
         \
  done\n\
         \
\n\
         \
  echo \"[cc-switch-tui] $alias_name: ${{(j: :)parts}}\" >&2\n\
         }}",
        keys_list
    )
}

fn format_function(
    name: &str,
    env: &HashMap<String, String>,
    unset_vars: &[String],
    kv_cache_enabled: bool,
) -> String {
    let mut pairs: Vec<_> = env.iter().collect();
    pairs.sort_by(|a, b| a.0.cmp(b.0));

    // ANTHROPIC_BASE_URL 由外部（如 ys-proxy）传入时保留，否则使用默认值
    let unset_vars_filtered: Vec<&str> = unset_vars
        .iter()
        .map(|s| s.as_str())
        .filter(|&s| s != "ANTHROPIC_BASE_URL")
        .collect();
    let unset_line = format!("  unset {}", unset_vars_filtered.join(" "));

    let base_url_value = env.get("ANTHROPIC_BASE_URL").cloned();
    let other_pairs: Vec<_> = pairs
        .into_iter()
        .filter(|(k, _)| *k != "ANTHROPIC_BASE_URL")
        .collect();

    let mut export_lines: Vec<String> = other_pairs
        .iter()
        .map(|(k, v)| format!("  export {}={}", k, shell_escape(v)))
        .collect();

    if let Some(base_url) = base_url_value {
        export_lines.push(format!(
            "  export ANTHROPIC_BASE_URL=\"${{ANTHROPIC_BASE_URL:-{}}}\"",
            shell_escape(&base_url)
        ));
    }
    export_lines.sort();
    let export_block = export_lines.join("\n");

    let claude_cmd = if kv_cache_enabled {
        "command claude --exclude-dynamic-system-prompt-sections --settings '{\"includeGitInstructions\":false}' \"$@\""
    } else {
        "command claude \"$@\""
    };

    format!(
        "function {} {{\n{}\n{}\n  __cc_switch_print_env {}\n  {}\n}}",
        name, unset_line, export_block, name, claude_cmd
    )
}

pub(crate) fn shell_escape(s: &str) -> String {
    if s.contains('\'') {
        format!("'{}'", s.replace('\'', "'\"'\"'"))
    } else if s
        .chars()
        .all(|c| c.is_ascii_alphanumeric() || "_.:-/".contains(c))
    {
        s.to_string()
    } else {
        format!("'{}'", s)
    }
}

/// 检查 zshrc 文件是否包含 source ~/.cc-switch-tui/aliases.zsh
pub fn ensure_zshrc_source(zshrc_path: &std::path::Path) -> std::io::Result<bool> {
    let source_line = "source ~/.cc-switch-tui/aliases.zsh";
    if zshrc_path.exists() {
        let content = fs::read_to_string(zshrc_path)?;
        if content.lines().any(|l| l.trim() == source_line) {
            return Ok(false);
        }
    }
    let mut file = fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(zshrc_path)?;
    writeln!(file, "{}", source_line)?;
    Ok(true)
}

